begin;

-- One activation mechanism for manual sessions and explicitly requested invites.
-- No owner password, caller-selected role, or user metadata authorization.
create function app_private.activate_bootstrap_owner(p_auth uuid,p_invitation boolean default false) returns jsonb
language plpgsql security definer set search_path='' as $$
declare sc public.shop_config%rowtype; bc app_private.bridge_config%rowtype;
 b app_private.owner_bootstrap%rowtype; u auth.users%rowtype; au public.app_users%rowtype;
begin
 select * into strict sc from public.shop_config where id=1 for update;
 select * into strict bc from app_private.bridge_config where singleton for update;
 select * into b from app_private.owner_bootstrap where singleton for update;
 if p_auth is null or not coalesce(b.singleton,false) or sc.onboarding_version<>2 or sc.suspended
  or sc.owner_email is distinct from b.payload->>'owner_email'
  or sc.platform_client_id is distinct from (b.payload->>'platform_client_id')::integer
  or bc.client_binding is distinct from b.payload->>'client_binding' then
  raise exception 'Owner activation unavailable' using errcode='42501';
 end if;
 select * into u from auth.users where id=p_auth;
 if u.id is null or lower(trim(u.email)) is distinct from b.payload->>'owner_email'
  or (not p_invitation and (u.email_confirmed_at is null or not bc.delivery_enabled or bc.usage_mode<>'bridge'))
  or (p_invitation and (u.invited_at is null or u.raw_user_meta_data->>'orbito_bootstrap_request' is distinct from b.request_id::text)) then
  raise exception 'Owner activation unavailable' using errcode='42501';
 end if;
 if (b.owner_auth_id is not null and b.owner_auth_id<>u.id)
  or (b.owner_auth_id is null and sc.onboarding_completed_at is not null)
  or exists(select 1 from public.app_users where role='Business Owner' and auth_user_id<>u.id) then
  raise exception 'Owner activation unavailable' using errcode='42501';
 end if;
 insert into public.app_users(auth_user_id,employee_id,email,display_name,role,status)
  values(u.id,null,b.payload->>'owner_email',b.payload->>'owner_name','Business Owner','Active') on conflict(auth_user_id) do nothing;
 select * into strict au from public.app_users where auth_user_id=u.id;
 if au.role<>'Business Owner' or au.status<>'Active' or au.employee_id is not null
  or lower(trim(au.email)) is distinct from b.payload->>'owner_email' then
  raise exception 'Owner activation unavailable' using errcode='42501';
 end if;
 update app_private.owner_bootstrap set owner_auth_id=u.id,lease_id=null,lease_until=null where singleton;
 update app_private.bridge_config set usage_mode='bridge',delivery_enabled=true where singleton;
 return jsonb_build_object('auth_user_id',au.auth_user_id,'employee_id',au.employee_id,'email',au.email,
  'display_name',au.display_name,'role',au.role,'status',au.status);
end $$;
revoke all on function app_private.activate_bootstrap_owner(uuid,boolean) from public,anon,authenticated,service_role;

create function public.activate_reserved_owner() returns jsonb
language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null then raise exception 'Authenticated owner required' using errcode='42501'; end if;
 return app_private.activate_bootstrap_owner(auth.uid(),false);
end $$;
revoke all on function public.activate_reserved_owner() from public,anon,service_role;
grant execute on function public.activate_reserved_owner() to authenticated;

create or replace function public.bridge_onboarding(p_action text,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare sc public.shop_config%rowtype; bc app_private.bridge_config%rowtype;
 b app_private.owner_bootstrap%rowtype; u auth.users%rowtype; au public.app_users%rowtype;
 lease uuid; modules jsonb; k text;
begin
 select * into strict sc from public.shop_config where id=1 for update;
 select * into strict bc from app_private.bridge_config where singleton for update;
 select * into b from app_private.owner_bootstrap where singleton for update;
 if p_action='config-read' then
  return jsonb_build_object('config',jsonb_build_object('repair_module_enabled',sc.repair_module_enabled,
   'inventory_module_enabled',sc.inventory_module_enabled,'technician_module_enabled',sc.technician_module_enabled,
   'live_tracking_enabled',sc.live_tracking_enabled,'ems_enabled',sc.ems_enabled,'ems_track_breaks',sc.ems_track_breaks,'suspended',sc.suspended));
 elsif p_action='config-write' then
  modules:=p_payload->'changes';
  if modules is null or jsonb_typeof(modules)<>'object' or modules='{}' or
   modules-array['repair_module_enabled','inventory_module_enabled','technician_module_enabled','live_tracking_enabled','ems_enabled','ems_track_breaks','suspended']<>'{}' then raise exception 'Invalid config'; end if;
  for k in select jsonb_object_keys(modules) loop if jsonb_typeof(modules->k)<>'boolean' then raise exception 'Invalid config'; end if; end loop;
  update public.shop_config set repair_module_enabled=coalesce((modules->>'repair_module_enabled')::boolean,repair_module_enabled),
   inventory_module_enabled=coalesce((modules->>'inventory_module_enabled')::boolean,inventory_module_enabled),
   technician_module_enabled=coalesce((modules->>'technician_module_enabled')::boolean,technician_module_enabled),
   live_tracking_enabled=coalesce((modules->>'live_tracking_enabled')::boolean,live_tracking_enabled),
   ems_enabled=coalesce((modules->>'ems_enabled')::boolean,ems_enabled),
   ems_track_breaks=coalesce((modules->>'ems_track_breaks')::boolean,ems_track_breaks) and coalesce((modules->>'ems_enabled')::boolean,ems_enabled),
   suspended=coalesce((modules->>'suspended')::boolean,suspended) where id=1;
  return public.bridge_onboarding('config-read','{}');
 elsif p_action='status' then
  if b.owner_auth_id is not null then select * into u from auth.users where id=b.owner_auth_id; end if;
  return jsonb_build_object('source_id',bc.source_id,'client_binding',bc.client_binding,
   'infrastructure',case when b.singleton and bc.delivery_enabled and bc.usage_mode='bridge' then 'ready' else 'pending' end,
   'owner_setup',case when b.owner_auth_id is not null and u.email_confirmed_at is not null then 'owner_active' else 'owner_setup_pending' end,
   'owner_invite',case when u.invited_at is not null and u.email_confirmed_at is not null then 'owner_invite_accepted' else coalesce(b.invite_state,'owner_invite_not_started') end,
   'onboarding',case when sc.onboarding_completed_at is null then 'onboarding_pending' else 'onboarding_complete' end,
   'onboarding_version',sc.onboarding_version,'config',(public.bridge_onboarding('config-read','{}')->'config'));
 elsif p_action in ('reserve','claim') then
  if p_payload is null or jsonb_typeof(p_payload)<>'object' or not(p_payload ?& array['request_id','platform_client_id','client_binding','business_name','owner_name','owner_email','billing_currency','shop_url','modules','paper_resupply_enabled','onboarding_version'])
   or p_payload->>'onboarding_version' is distinct from '2' or coalesce((p_payload->>'platform_client_id')::integer,0)<1
   or length(coalesce(p_payload->>'client_binding','')) not between 1 and 200
   or length(coalesce(p_payload->>'business_name','')) not between 1 and 200
   or length(coalesce(p_payload->>'owner_name','')) not between 1 and 160
   or coalesce(p_payload->>'owner_email','') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
   or coalesce(p_payload->>'billing_currency','') !~ '^[A-Z]{3}$'
   or p_payload-array['request_id','platform_client_id','client_binding','business_name','owner_name','owner_email','billing_currency','shop_url','modules','paper_resupply_enabled','onboarding_version']<>'{}'
   then raise exception 'Invalid bootstrap'; end if;
  if (p_payload->>'request_id')::uuid is null then raise exception 'Request identity required'; end if;
  modules:=p_payload->'modules';
  if modules is null or jsonb_typeof(modules)<>'object' or not(modules ?& array['repair_module_enabled','inventory_module_enabled','technician_module_enabled','live_tracking_enabled','ems_enabled','ems_track_breaks'])
   or modules-array['repair_module_enabled','inventory_module_enabled','technician_module_enabled','live_tracking_enabled','ems_enabled','ems_track_breaks']<>'{}'
   or jsonb_typeof(p_payload->'paper_resupply_enabled')<>'boolean' then raise exception 'Invalid modules'; end if;
  for k in select jsonb_object_keys(modules) loop if jsonb_typeof(modules->k)<>'boolean' then raise exception 'Invalid modules'; end if; end loop;
  if (modules->>'ems_track_breaks')::boolean and not(modules->>'ems_enabled')::boolean then raise exception 'Break tracking requires EMS'; end if;
  if b.singleton then
   if b.payload-'request_id' <> p_payload-'request_id' then raise exception 'Conflicting bootstrap identity'; end if;
   if b.owner_auth_id is not null then
    select * into strict au from public.app_users where auth_user_id=b.owner_auth_id;
    select * into strict u from auth.users where id=b.owner_auth_id;
    if au.role<>'Business Owner' or au.status<>'Active' or au.employee_id is not null
     or lower(au.email)<>p_payload->>'owner_email' or lower(u.email)<>p_payload->>'owner_email' then raise exception 'Conflicting owner'; end if;
    return public.bridge_onboarding('status','{}')||jsonb_build_object('already_provisioned',true);
   end if;
  else
   if sc.onboarding_completed_at is not null or sc.platform_client_id is not null or bc.last_sequence<>0
    or bc.delivery_enabled or (bc.client_binding is not null and bc.client_binding<>p_payload->>'client_binding')
    or exists(select 1 from public.app_users where role<>'Orbito Support')
    or exists(select 1 from public.employees) or exists(select 1 from public.legacy_auth_credentials)
    or exists(select 1 from auth.users where lower(email)=p_payload->>'owner_email') then raise exception 'Shop is initialized or owner conflicts'; end if;
   insert into app_private.owner_bootstrap(request_id,payload) values((p_payload->>'request_id')::uuid,p_payload) returning * into b;
   update public.shop_config set platform_client_id=(p_payload->>'platform_client_id')::integer,
    shop_name=p_payload->>'business_name',owner_email=p_payload->>'owner_email',onboarding_version=2,
    currency=case p_payload->>'billing_currency' when 'PKR' then 'Rs.' when 'USD' then '$' when 'EUR' then '€' when 'GBP' then '£' else p_payload->>'billing_currency' end,
    repair_module_enabled=(modules->>'repair_module_enabled')::boolean,inventory_module_enabled=(modules->>'inventory_module_enabled')::boolean,
    technician_module_enabled=(modules->>'technician_module_enabled')::boolean,live_tracking_enabled=(modules->>'live_tracking_enabled')::boolean,
    ems_enabled=(modules->>'ems_enabled')::boolean,ems_track_breaks=(modules->>'ems_track_breaks')::boolean,
    paper_resupply_enabled=(p_payload->>'paper_resupply_enabled')::boolean where id=1;
   update app_private.bridge_config set client_binding=p_payload->>'client_binding' where singleton;
  end if;
  if p_action='reserve' then
   update app_private.bridge_config set usage_mode='bridge',delivery_enabled=true where singleton;
   return public.bridge_onboarding('status','{}');
  end if;
  if b.lease_until>clock_timestamp() then raise exception 'Bootstrap in progress'; end if;
  -- Recover an Auth invite committed before a lost HTTP response. Do not adopt a
  -- pre-existing account: the reservation predates this Auth identity.
  select * into u from auth.users where lower(email)=p_payload->>'owner_email';
  if u.id is not null then
   if u.invited_at is null or u.raw_user_meta_data->>'orbito_bootstrap_request' is distinct from b.request_id::text
    or exists(select 1 from public.app_users where auth_user_id=u.id and role<>'Business Owner') then raise exception 'Conflicting auth identity'; end if;
   -- Metadata is only a recovery correlation, never a role authorization source.
   perform public.bridge_onboarding('finish',jsonb_build_object('auth_user_id',u.id));
   return public.bridge_onboarding('status','{}')||jsonb_build_object('already_provisioned',true);
  end if;
  lease:=gen_random_uuid();
  update app_private.owner_bootstrap set lease_id=lease,lease_until=clock_timestamp()+interval '2 minutes' where singleton;
  return jsonb_build_object('lease_id',lease,'request_id',b.request_id);
 elsif p_action='finish' then
  perform app_private.activate_bootstrap_owner((p_payload->>'auth_user_id')::uuid,true);
  update app_private.owner_bootstrap set invite_state='owner_invite_sent',invite_sent_at=coalesce(invite_sent_at,now()) where singleton;
  return public.bridge_onboarding('status','{}');
 elsif p_action='failed' then
  update app_private.owner_bootstrap set invite_state='owner_invite_failed',lease_id=null,lease_until=null
   where singleton and lease_id=(p_payload->>'lease_id')::uuid;
  return '{}'::jsonb;
 else raise exception 'Unsupported onboarding action'; end if;
end $$;
revoke all on function public.bridge_onboarding(text,jsonb) from public,anon,authenticated;
grant execute on function public.bridge_onboarding(text,jsonb) to service_role;


commit;

-- Edge Functions use the built-in service_role client for trusted
-- Shop runtime state reads. RLS remains enabled for browser roles.
grant select on table public.shop_config to service_role;

begin;
-- BYPASSRLS does not grant table privileges. Explicit Edge dependencies only.
grant usage on schema public to service_role;
grant select on public.shop_config,public.employees,public.tickets to service_role;
grant update(shop_name,shop_address,shop_phone,shop_email,shop_logo,shop_description,
 primary_color,secondary_color,currency,tax_rate,discount_pin_required,
 partial_udhar_allowed,terms_text,invoice_prefix,ticket_prefix,owner_email)
 on public.shop_config to service_role;
grant insert,update,delete on public.employees to service_role;
grant select,insert,update on public.password_reset_requests to service_role;
grant usage,select on sequence public.employees_id_seq,public.password_reset_requests_id_seq to service_role;
-- Browser config access stays through the existing authorized RPC, not the table.
revoke all on public.shop_config from anon,authenticated;

create function public.bridge_runtime_preflight() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare checks jsonb; table_ok boolean; rpc_ok boolean; settings_ok boolean;
 sc public.shop_config%rowtype; bc app_private.bridge_config%rowtype; b app_private.owner_bootstrap%rowtype;
 account text; candidates integer; confirmed boolean;
begin
 select * into strict sc from public.shop_config where id=1;
 select * into strict bc from app_private.bridge_config where singleton;
 select * into b from app_private.owner_bootstrap where singleton;
 select bool_and(coalesce(has_table_privilege('service_role',to_regclass(t),p),false)) into table_ok
 from (values ('public.shop_config','SELECT'),('public.app_users','SELECT'),('public.app_users','INSERT'),
 ('public.app_users','UPDATE'),('public.app_users','DELETE'),('public.employees','SELECT'),
 ('public.employees','INSERT'),('public.employees','UPDATE'),('public.employees','DELETE'),
 ('public.legacy_auth_credentials','SELECT'),('public.legacy_auth_credentials','UPDATE'),('public.legacy_auth_credentials','DELETE'),
 ('public.password_reset_requests','SELECT'),('public.password_reset_requests','INSERT'),('public.password_reset_requests','UPDATE'),
 ('public.support_access_log','SELECT'),('public.support_access_log','INSERT'),('public.tickets','SELECT')) required(t,p);
 select bool_and(coalesce(has_column_privilege('service_role','public.shop_config',k,'UPDATE'),false)) into settings_ok
 from unnest(array['shop_name','shop_address','shop_phone','shop_email','shop_logo','shop_description',
 'primary_color','secondary_color','currency','tax_rate','discount_pin_required','partial_udhar_allowed',
 'terms_text','invoice_prefix','ticket_prefix','owner_email']) k;
 select bool_and(coalesce(has_function_privilege(r,to_regprocedure(f),'EXECUTE'),false)) into rpc_ok
 from (values ('service_role','public.bridge_onboarding(text,jsonb)'),('service_role','public.complete_shop_onboarding(uuid)'),
 ('service_role','public.set_override_pin(text)'),('service_role','public.verify_override_pin_guarded(uuid,text,text)'),
 ('service_role','public.verify_legacy_credential(text,text)'),('service_role','public.bridge_claim_outbox(integer)'),
 ('service_role','public.bridge_finish_delivery(uuid,uuid,boolean)'),('service_role','public.bridge_apply_billing(uuid,bigint,jsonb)'),
 ('service_role','public.bridge_apply_resupply(uuid,uuid,bigint,text,timestamp with time zone)'),
 ('authenticated','public.activate_reserved_owner()'),('authenticated','public.get_app_config()')) required(r,f);
 checks:=jsonb_build_object('migrations',sc.onboarding_version in(0,2) and to_regprocedure('app_private.activate_bootstrap_owner(uuid,boolean)') is not null,
  'database_privileges',coalesce(table_ok and settings_ok,false),
  'rpc_privileges',coalesce(rpc_ok,false),
  'sequence_privileges',has_sequence_privilege('service_role','public.employees_id_seq','USAGE') and has_sequence_privilege('service_role','public.password_reset_requests_id_seq','USAGE') and has_sequence_privilege('service_role','public.support_access_log_id_seq','USAGE'),
  'private_config',not has_any_column_privilege('anon','public.shop_config','SELECT') and not has_any_column_privilege('authenticated','public.shop_config','SELECT') and not has_any_column_privilege('authenticated','public.shop_config','UPDATE'),
  'storage',true,
  'owner_reservation',coalesce(b.singleton and sc.onboarding_version=2 and sc.platform_client_id=(b.payload->>'platform_client_id')::integer and sc.owner_email=b.payload->>'owner_email' and bc.client_binding=b.payload->>'client_binding',false),
  'bridge_mode',bc.delivery_enabled and bc.usage_mode='bridge',
  'config_projection',exists(select 1 from app_private.billing_projection where singleton));
 select count(*),bool_and(email_confirmed_at is not null) into candidates,confirmed
 from auth.users where lower(trim(email))=b.payload->>'owner_email';
 account:=case when candidates>1 then 'conflict'
  when exists(select 1 from public.app_users u where (u.role='Business Owner' or lower(trim(u.email))=b.payload->>'owner_email')
   and (u.role<>'Business Owner' or u.status<>'Active' or u.employee_id is not null or lower(trim(u.email)) is distinct from b.payload->>'owner_email'
    or not exists(select 1 from auth.users a where a.id=u.auth_user_id and lower(trim(a.email))=b.payload->>'owner_email'))) then 'conflict'
  when b.owner_auth_id is not null and confirmed and exists(
  select 1 from public.app_users u join auth.users a on a.id=u.auth_user_id
  where u.auth_user_id=b.owner_auth_id and u.role='Business Owner' and u.status='Active' and u.employee_id is null
   and lower(trim(a.email))=b.payload->>'owner_email' and lower(trim(u.email))=b.payload->>'owner_email'
  ) then 'active'
  when b.owner_auth_id is not null and (confirmed or not exists(select 1 from auth.users where id=b.owner_auth_id and lower(trim(email))=b.payload->>'owner_email')) then 'conflict'
  when candidates=0 then 'missing' when confirmed then 'ready' else 'unconfirmed' end;
 return jsonb_build_object('checks',checks,'owner_account',account);
end $$;
revoke all on function public.bridge_runtime_preflight() from public,anon,authenticated;
grant execute on function public.bridge_runtime_preflight() to service_role;
commit;

begin;
-- Per-client project tenancy: random local Shop identity, never caller supplied.
-- Future version changes update legal_policy through a reviewed forward migration.
create table app_private.legal_policy (
  singleton boolean primary key default true check (singleton),
  shop_id uuid not null unique default extensions.gen_random_uuid(),
  published boolean not null default false,
  required_revision text not null,
  terms_version text not null,
  privacy_version text not null,
  dpa_version text not null
);
insert into app_private.legal_policy
  (singleton, required_revision, terms_version, privacy_version, dpa_version)
values (true, '2026-09-27.1', '[PLACEHOLDER: TERMS_VERSION]', '[PLACEHOLDER: PRIVACY_VERSION]', '[PLACEHOLDER: DPA_VERSION]');

create table app_private.legal_acceptances (
  id uuid primary key default extensions.gen_random_uuid(),
  shop_id uuid not null references app_private.legal_policy(shop_id),
  auth_user_id uuid not null,
  accepted_name text not null check (accepted_name ~ '[^[:space:]]'),
  accepted_role text not null check (accepted_role = 'Business Owner'),
  required_revision text not null,
  terms_version text not null,
  privacy_version text not null,
  dpa_version text not null,
  accepted_at timestamptz not null default clock_timestamp(),
  unique (shop_id, required_revision)
);
-- No Auth FK/cascade: removing an account must not erase contracting evidence.
-- Personal-data retention of this evidence is an explicit business/legal decision.
alter table app_private.legal_policy enable row level security;
alter table app_private.legal_acceptances enable row level security;
revoke all on app_private.legal_policy, app_private.legal_acceptances from public, anon, authenticated;
grant all on app_private.legal_policy, app_private.legal_acceptances to service_role;

create function public.get_legal_status()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  policy app_private.legal_policy%rowtype;
  receipt app_private.legal_acceptances%rowtype;
begin
  if auth.uid() is null or not app_private.current_client_access_allowed()
    or app_private.current_app_role() is distinct from 'Business Owner' then
    raise exception 'Owner access required' using errcode = '42501';
  end if;
  select * into strict policy from app_private.legal_policy where singleton;
  select * into receipt from app_private.legal_acceptances
    where shop_id = policy.shop_id order by accepted_at desc, id desc limit 1;
  return jsonb_build_object(
    'published', policy.published,
    'required_revision', policy.required_revision,
    'terms_version', policy.terms_version,
    'privacy_version', policy.privacy_version,
    'dpa_version', policy.dpa_version,
    'accepted', exists(select 1 from app_private.legal_acceptances
      where shop_id = policy.shop_id and required_revision = policy.required_revision),
    'receipt', case when receipt.id is null then null else jsonb_build_object(
      'accepted_name', receipt.accepted_name, 'accepted_role', receipt.accepted_role,
      'accepted_at', receipt.accepted_at, 'required_revision', receipt.required_revision,
      'terms_version', receipt.terms_version, 'privacy_version', receipt.privacy_version,
      'dpa_version', receipt.dpa_version) end);
end $$;
revoke all on function public.get_legal_status() from public, anon;
grant execute on function public.get_legal_status() to authenticated;

create function public.accept_legal_terms(
  p_authorized boolean, p_required_revision text,
  p_terms_version text, p_privacy_version text, p_dpa_version text
)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  policy app_private.legal_policy%rowtype;
  actor public.app_users%rowtype;
begin
  if auth.uid() is null or not app_private.current_client_access_allowed() then
    raise exception 'Owner access required' using errcode = '42501';
  end if;
  select * into actor from public.app_users
    where auth_user_id = auth.uid() and status = 'Active' for share;
  if actor.role is distinct from 'Business Owner' then
    raise exception 'Only the Business Owner may accept' using errcode = '42501';
  end if;
  if actor.display_name is null or actor.display_name !~ '[^[:space:]]' then
    raise exception 'Business Owner name is required before accepting legal terms' using errcode = '22023';
  end if;
  if p_authorized is distinct from true then
    raise exception 'Confirm your authority to accept' using errcode = '22023';
  end if;
  -- Serialize policy updates against acceptance; dates, identity and Shop are server-derived.
  select * into strict policy from app_private.legal_policy where singleton for share;
  if not policy.published then
    raise exception 'Legal documents are being finalized.' using errcode = '22023';
  end if;
  if p_required_revision is distinct from policy.required_revision
    or p_terms_version is distinct from policy.terms_version
    or p_privacy_version is distinct from policy.privacy_version
    or p_dpa_version is distinct from policy.dpa_version then
    raise exception 'Legal documents changed. Reload and review them.' using errcode = '22023';
  end if;
  insert into app_private.legal_acceptances
    (shop_id, auth_user_id, accepted_name, accepted_role, required_revision,
     terms_version, privacy_version, dpa_version)
  values (policy.shop_id, auth.uid(), actor.display_name, actor.role, policy.required_revision,
    policy.terms_version, policy.privacy_version, policy.dpa_version)
  on conflict (shop_id, required_revision) do nothing;
  return public.get_legal_status();
end $$;
revoke all on function public.accept_legal_terms(boolean,text,text,text,text) from public, anon;
grant execute on function public.accept_legal_terms(boolean,text,text,text,text) to authenticated;

-- Public reader gets publication/version metadata only; never identity or acceptance evidence.
create function public.get_legal_publication()
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('published', published, 'required_revision', required_revision,
    'terms_version', terms_version, 'privacy_version', privacy_version, 'dpa_version', dpa_version)
  from app_private.legal_policy where singleton
$$;
revoke all on function public.get_legal_publication() from public;
grant execute on function public.get_legal_publication() to anon, authenticated;
commit;

-- Preserve the bridge operation/response contract; journal the request identity
-- already supplied by Platform. Legacy callers without an ID retain old behavior.
begin;
create table app_private.config_requests (
 request_id uuid primary key, changes jsonb not null, result jsonb not null,
 created_at timestamptz not null default now()
);
alter table app_private.config_requests enable row level security;
revoke all on app_private.config_requests from public,anon,authenticated;
grant select,insert on app_private.config_requests to service_role;
alter function public.bridge_onboarding(text,jsonb) rename to bridge_onboarding_v1;
create function public.bridge_onboarding(p_action text,p_payload jsonb default '{}') returns jsonb
language plpgsql security definer set search_path='' as $$
declare old app_private.config_requests%rowtype; response jsonb; request uuid;
begin
 if p_action<>'config-write' or not (p_payload ? 'request_id') then return public.bridge_onboarding_v1(p_action,p_payload); end if;
 request:=(p_payload->>'request_id')::uuid;
 if request is null then raise exception 'Configuration request identity required'; end if;
 -- Same lock order as the existing bridge. Durable replay never reapplies a
 -- previous write after a later successful operation.
 perform 1 from app_private.bridge_config where singleton for update;
 select * into old from app_private.config_requests where request_id=request;
 if found then
  if old.changes is distinct from p_payload->'changes' then raise exception 'Configuration request identity conflict'; end if;
  return old.result;
 end if;
 response:=public.bridge_onboarding_v1(p_action,p_payload);
 insert into app_private.config_requests(request_id,changes,result) values(request,p_payload->'changes',response);
 return response;
end $$;
revoke all on function public.bridge_onboarding_v1(text,jsonb),public.bridge_onboarding(text,jsonb) from public,anon,authenticated;
grant execute on function public.bridge_onboarding(text,jsonb) to service_role;
commit;

