export const RUNTIME_CONTRACT = 'orbito-onboarding-runtime-v1'
export const REQUIRED_FUNCTIONS = ['login','account-admin','verify-pin','password-reset-request','public-track']

export async function runtimeProbe(req: Request, name: string, required: string[]) {
  if (!req.headers.has('x-orbito-preflight')) return null
  const supplied = req.headers.get('x-orbito-preflight') || ''
  const expected = Deno.env.get('PLATFORM_BRIDGE_CALL_SECRET') || ''
  const digest = async (value: string) => new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))
  const [a,b] = await Promise.all([digest(supplied),digest(expected)])
  if (req.method !== 'POST' || !expected || !supplied || a.reduce((n,v,i)=>n|(v^b[i]),0)) return Response.json({error:'Not authorized'},{status:401})
  return Response.json({contract:RUNTIME_CONTRACT,function:name,configured:required.every(k=>Boolean(Deno.env.get(k)?.trim())),runtime_checks:Object.fromEntries(required.map(k=>[k,Boolean(Deno.env.get(k)?.trim())]))},
    {headers:{'Cache-Control':'no-store'}})
}

export async function checkRuntime(admin: any, status: any) {
  let data: any, error: any
  try { ({data,error} = await admin.rpc('bridge_runtime_preflight')) } catch { error = true }
  const checks = {...data?.checks}
  if (error) checks.migrations = false
  // Exercise PostgREST under the actual Edge service client, not just a definer.
  try {
    const read = await admin.from('shop_config').select('id').eq('id',1).single()
    checks.database_reachable = !read.error && read.data?.id === 1
  } catch { checks.database_reachable = false }
  const url = Deno.env.get('SUPABASE_URL') || ''
  const anon = Deno.env.get('SUPABASE_ANON_KEY') || ''
  const call = Deno.env.get('PLATFORM_BRIDGE_CALL_SECRET') || ''
  const source = Deno.env.get('PLATFORM_BRIDGE_SOURCE_SECRET') || ''
  const endpoint = Deno.env.get('PLATFORM_BRIDGE_ENDPOINT') || ''
  let validEndpoint = false
  try { const target = new URL(endpoint);validEndpoint = target.protocol==='https:' && !target.username && !target.password && !target.search && !target.hash && target.pathname==='/functions/v1/platform-bridge' && target.origin!==url } catch {}
  checks.bridge_configuration = Boolean(call && source && call!==source && validEndpoint)
  const functions = await Promise.all(REQUIRED_FUNCTIONS.map(async name => {
    try {
      const response = await fetch(`${url}/functions/v1/${name}`,{method:'POST',redirect:'error',signal:AbortSignal.timeout(5000),
        headers:{Authorization:`Bearer ${anon}`,apikey:anon,'x-orbito-preflight':call,'Content-Type':'application/json'},body:'{}'})
      if (!response.ok) { await response.body?.cancel();return [name,false,false,false] }
      const result = await response.json()
      const deployed = result?.contract===RUNTIME_CONTRACT && result.function===name
      return [name,deployed,deployed && result.configured===true,deployed && result.runtime_checks?.TURNSTILE_SECRET===true]
    } catch { return [name,false,false,false] }
  }))
  checks.edge_functions = functions.every(([,deployed])=>deployed===true)
  checks.runtime_configuration = functions.every(([, ,configured])=>configured===true)
  let authAvailable = false
  try {
    const auth = await admin.auth.admin.listUsers({page:1,perPage:1})
    authAvailable = !auth.error && Array.isArray(auth.data?.users)
  } catch { /* No Auth bodies or identities leave the preflight. */ }
  checks.authentication = authAvailable && functions.find(([name])=>name==='login')?.[2]===true && checks.database_privileges===true && checks.rpc_privileges===true
  const keys = ['migrations','database_privileges','rpc_privileges','sequence_privileges','private_config','storage',
    'owner_reservation','bridge_mode','config_projection','database_reachable','bridge_configuration','edge_functions','runtime_configuration','authentication']
  const safeChecks = Object.fromEntries(keys.map(k=>[k,checks[k]===true]))
  const ownerAccount = ['missing','unconfirmed','ready','active','conflict'].includes(data?.owner_account) ? data.owner_account : 'missing'
  return {...status,contract:RUNTIME_CONTRACT,checks:safeChecks,owner_account:ownerAccount,
    runtime_details:{functions:Object.fromEntries(functions.map(([name,deployed])=>[name,deployed===true])),turnstile:functions.filter(([name])=>['login','password-reset-request'].includes(String(name))).every(([, , ,turnstile])=>turnstile===true)},
    infrastructure:keys.every(k=>safeChecks[k]) && ownerAccount!=='conflict' ? 'ready':'pending'}
}

import { runtimeProbe } from '../_shared/runtime-preflight.ts'
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.108.2'

const SUPABASE_URL = Deno.env.get('SUPABASE_URL') ?? ''
const SUPABASE_ANON = Deno.env.get('SUPABASE_ANON_KEY') ?? ''
const SUPABASE_SERVICE_ROLE = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

type Role = 'Business Owner' | 'Manager' | 'Cashier' | 'Technician' | 'Orbito Support'
type Profile = {
  auth_user_id: string
  employee_id: number | null
  email: string
  display_name: string
  role: Role
  status: 'Active' | 'Inactive'
}

const employeeRoles: Role[] = ['Manager', 'Cashier', 'Technician']
const statuses = ['Active', 'Inactive']
const configKeys = new Set([
  'shop_name', 'shop_address', 'shop_phone', 'shop_email', 'shop_logo', 'shop_description',
  'primary_color', 'secondary_color', 'currency', 'tax_rate',
  'discount_pin_required', 'partial_udhar_allowed', 'terms_text',
  'invoice_prefix', 'ticket_prefix',
])

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: { ...CORS, 'Content-Type': 'application/json' } })
}
const emailOf = (value: unknown) => String(value ?? '').toLowerCase().trim()
const goodPassword = (value: unknown) => {
  const password = String(value ?? '')
  return password.length >= 8 && /[A-Za-z]/.test(password) && /[0-9]/.test(password) && /[^A-Za-z0-9]/.test(password)
}
const canManage = (caller: Role, target: Role) => {
  if (caller === 'Manager') return target === 'Cashier' || target === 'Technician'
  if (caller === 'Business Owner' || caller === 'Orbito Support') return employeeRoles.includes(target)
  return false
}

async function context(req: Request) {
  if (!SUPABASE_URL || !SUPABASE_ANON || !SUPABASE_SERVICE_ROLE) throw new Error('Server configuration is incomplete.')
  const authorization = req.headers.get('authorization') ?? ''
  const token = authorization.match(/^Bearer\s+(.+)$/i)?.[1]
  if (!token) return null

  const opts = { auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false } }
  const userClient = createClient(SUPABASE_URL, SUPABASE_ANON, opts)
  const admin = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE, opts)
  const { data: userData, error: userError } = await userClient.auth.getUser(token)
  if (userError || !userData.user) return null
  const { data: caller, error: callerError } = await admin
    .from('app_users')
    .select('auth_user_id, employee_id, email, display_name, role, status')
    .eq('auth_user_id', userData.user.id)
    .single()
  if (callerError || !caller || caller.status !== 'Active') return null
  const { data: shop, error: shopError } = await admin.from('shop_config').select('suspended').eq('id', 1).single()
  if (shopError || !shop) return null
  if (shop.suspended && caller.role !== 'Orbito Support') return null
  return { admin, caller: caller as Profile }
}

async function createEmployee(admin: any, caller: Profile, body: any) {
  const name = String(body.name ?? '').trim()
  const email = emailOf(body.email)
  const role = String(body.role ?? 'Cashier') as Role
  const password = String(body.password ?? '')
  if (!name || !email || !goodPassword(password) || !employeeRoles.includes(role)) {
    return { ok: false, error: 'Valid name, email, role, and password are required.' }
  }
  if (!canManage(caller.role, role)) return { ok: false, error: 'You cannot create that role.' }

  const { data: created, error: createError } = await admin.auth.admin.createUser({ email, password, email_confirm: true })
  if (createError || !created.user) return { ok: false, error: 'That email is unavailable or the Auth user could not be created.' }
  const { data: employee, error: employeeError } = await admin
    .from('employees')
    .insert({ name, email, role, status: 'Active', password: null, pin_code: null })
    .select('id')
    .single()
  if (employeeError || !employee) {
    await admin.auth.admin.deleteUser(created.user.id)
    return { ok: false, error: 'Employee record could not be created.' }
  }
  const { error: mappingError } = await admin.from('app_users').insert({
    auth_user_id: created.user.id,
    employee_id: employee.id,
    email,
    display_name: name,
    role,
    status: 'Active',
  })
  if (mappingError) {
    await admin.from('employees').delete().eq('id', employee.id)
    await admin.auth.admin.deleteUser(created.user.id)
    return { ok: false, error: 'Employee authorization mapping could not be created.' }
  }
  return { ok: true, employeeId: employee.id }
}

async function updateEmployee(admin: any, caller: Profile, body: any) {
  const employeeId = Number(body.employeeId)
  const { data: employee, error } = await admin
    .from('employees').select('id, name, email, role, status').eq('id', employeeId).single()
  if (error || !employee) return { ok: false, error: 'Employee not found.' }
  const role = String(body.role ?? employee.role) as Role
  const status = String(body.status ?? employee.status)
  const name = String(body.name ?? employee.name).trim()
  const email = emailOf(body.email ?? employee.email)
  if (!name || !email || !employeeRoles.includes(role) || !statuses.includes(status)) {
    return { ok: false, error: 'Invalid employee update.' }
  }
  if (!canManage(caller.role, employee.role) || !canManage(caller.role, role)) {
    return { ok: false, error: 'You cannot edit that account or assign that role.' }
  }

  const { data: mapped, error: mappedError } = await admin
    .from('app_users')
    .select('auth_user_id, email')
    .eq('employee_id', employeeId)
    .maybeSingle()
  if (mappedError) return { ok: false, error: 'Authorization mapping lookup failed.' }

  if (mapped && email !== mapped.email) {
    const { error: authError } = await admin.auth.admin.updateUserById(mapped.auth_user_id, { email, email_confirm: true })
    if (authError) return { ok: false, error: 'Auth email could not be updated.' }
  }
  if (!mapped && email !== emailOf(employee.email)) {
    const { error: vaultEmailError } = await admin.from('legacy_auth_credentials')
      .update({ normalized_email: email }).eq('normalized_email', emailOf(employee.email))
    if (vaultEmailError) return { ok: false, error: 'Legacy identity email could not be updated.' }
  }
  const { error: employeeUpdateError } = await admin
    .from('employees').update({ name, email, role, status }).eq('id', employeeId)
  if (employeeUpdateError) {
    if (mapped && email !== mapped.email) {
      await admin.auth.admin.updateUserById(mapped.auth_user_id, { email: mapped.email, email_confirm: true })
    }
    if (!mapped && email !== emailOf(employee.email)) {
      await admin.from('legacy_auth_credentials')
        .update({ normalized_email: emailOf(employee.email) }).eq('normalized_email', email)
    }
    return { ok: false, error: 'Employee record could not be updated.' }
  }

  if (mapped) {
    const { error: mappingUpdateError } = await admin.from('app_users').update({
      email, display_name: name, role, status,
    }).eq('auth_user_id', mapped.auth_user_id)
    if (mappingUpdateError) {
      await admin.from('employees').update({
        name: employee.name, email: employee.email, role: employee.role, status: employee.status,
      }).eq('id', employeeId)
      if (email !== mapped.email) {
        await admin.auth.admin.updateUserById(mapped.auth_user_id, { email: mapped.email, email_confirm: true })
      }
      return { ok: false, error: 'Authorization mapping could not be updated.' }
    }
  }
  return { ok: true }
}

async function targetByEmail(admin: any, email: string) {
  const { data: mapped } = await admin
    .from('app_users')
    .select('auth_user_id, employee_id, email, display_name, role, status')
    .eq('email', email)
    .maybeSingle()
  if (mapped) return { profile: mapped as Profile, employee: null }

  const { data: owner } = await admin.from('shop_config').select('owner_email').eq('id', 1).single()
  if (emailOf(owner?.owner_email) === email) {
    return {
      profile: null,
      employee: { id: null, name: 'Admin', email, role: 'Business Owner', status: 'Active' },
    }
  }
  const { data: employee } = await admin
    .from('employees').select('id, name, email, role, status').ilike('email', email).maybeSingle()
  return { profile: null, employee }
}

async function resetPassword(admin: any, caller: Profile, body: any) {
  const email = emailOf(body.email)
  const password = String(body.newPassword ?? '')
  if (!email || !goodPassword(password)) return { ok: false, error: 'A valid target and password are required.' }
  const target = await targetByEmail(admin, email)
  const targetRole = (target.profile?.role ?? target.employee?.role) as Role | undefined
  if (!targetRole) return { ok: false, error: 'Target account was not found.' }
  const allowed = canManage(caller.role, targetRole) || (caller.role === 'Orbito Support' && targetRole === 'Business Owner')
  if (!allowed) return { ok: false, error: 'You cannot reset that account.' }

  if (target.profile) {
    const { error } = await admin.auth.admin.updateUserById(target.profile.auth_user_id, { password })
    if (error) return { ok: false, error: 'Password could not be reset.' }
    await admin.from('legacy_auth_credentials').delete().eq('normalized_email', email)
    return { ok: true }
  }

  const { data: created, error: createError } = await admin.auth.admin.createUser({ email, password, email_confirm: true })
  if (createError || !created.user) return { ok: false, error: 'Auth identity could not be created.' }
  const employeeId = target.employee.id ?? null
  const profile = {
    auth_user_id: created.user.id,
    employee_id: employeeId,
    email,
    display_name: target.employee.name,
    role: targetRole,
    status: target.employee.status,
  }
  const { error: mapError } = await admin.from('app_users').insert(profile)
  if (mapError) {
    await admin.auth.admin.deleteUser(created.user.id)
    return { ok: false, error: 'Authorization mapping could not be created.' }
  }
  const { error: consumeError } = await admin.from('legacy_auth_credentials').delete().eq('normalized_email', email)
  if (consumeError) return { ok: false, error: 'Legacy credential cleanup is pending; retry through support.' }
  return { ok: true }
}

async function updateOwner(admin: any, caller: Profile, body: any) {
  if (caller.role !== 'Business Owner' && caller.role !== 'Orbito Support') {
    return { ok: false, error: 'Owner settings are not permitted.' }
  }
  const email = emailOf(body.email)
  if (!email) return { ok: false, error: 'A valid owner email is required.' }
  const { data: shop, error: shopError } = await admin.from('shop_config').select('onboarding_version').eq('id', 1).single()
  if (shopError || !shop) return { ok: false, error: 'Owner identity could not be checked.' }
  if (shop.onboarding_version === 2) return { ok: false, error: 'The invited Business Owner identity cannot be changed through ordinary settings.' }
  const { data: owner } = await admin.from('app_users').select('*').eq('role', 'Business Owner').maybeSingle()
  if (!owner) return { ok: false, error: 'Owner must complete Auth migration before changing email.' }
  const oldEmail = owner.email
  const { error: authError } = await admin.auth.admin.updateUserById(owner.auth_user_id, { email, email_confirm: true })
  if (authError) return { ok: false, error: 'Owner Auth email could not be updated.' }
  const { error: mapError } = await admin.from('app_users').update({ email }).eq('auth_user_id', owner.auth_user_id)
  if (mapError) {
    await admin.auth.admin.updateUserById(owner.auth_user_id, { email: oldEmail, email_confirm: true })
    return { ok: false, error: 'Owner mapping could not be updated.' }
  }
  const { error: configError } = await admin.from('shop_config').update({ owner_email: email }).eq('id', 1)
  if (configError) {
    await admin.from('app_users').update({ email: oldEmail }).eq('auth_user_id', owner.auth_user_id)
    await admin.auth.admin.updateUserById(owner.auth_user_id, { email: oldEmail, email_confirm: true })
    return { ok: false, error: 'Owner configuration could not be updated.' }
  }
  return { ok: true }
}

async function updateConfig(admin: any, caller: Profile, body: any) {
  if (caller.role !== 'Business Owner' && caller.role !== 'Orbito Support') {
    return { ok: false, error: 'Settings changes are not permitted.' }
  }
  const updates: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(body.updates ?? {})) {
    if (configKeys.has(key)) updates[key] = value
  }
  if (updates.tax_rate !== undefined && (typeof updates.tax_rate !== 'number' || !Number.isFinite(updates.tax_rate) || updates.tax_rate<0 || updates.tax_rate>100)) return { ok:false,error:'Tax rate must be between 0 and 100.' }
  if (updates.shop_email !== undefined && updates.shop_email !== '' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(updates.shop_email))) return { ok:false,error:'Valid business email required.' }
  if (updates.shop_logo !== undefined) {
    let valid = false
    if (typeof updates.shop_logo==='string' && updates.shop_logo.length<=699100) {
      const encoded = /^data:image\/(png|jpeg|webp);base64,([A-Za-z0-9+/]+={0,2})$/.exec(updates.shop_logo)?.[2]
      try { valid = Boolean(encoded && encoded.length%4===0 && atob(encoded).length<=512*1024) } catch {}
    }
    if (!valid) return {ok:false,error:'Choose a PNG, JPEG or WebP logo under 512 KB.'}
  }
  if (!Object.keys(updates).length) return { ok: false, error: 'No permitted settings were provided.' }
  const { error } = await admin.from('shop_config').update(updates).eq('id', 1)
  return error ? { ok: false, error: 'Settings could not be updated.' } : { ok: true }
}

Deno.serve(async (req: Request) => {
  const preflight = await runtimeProbe(req,'account-admin',["SUPABASE_URL","SUPABASE_ANON_KEY","SUPABASE_SERVICE_ROLE_KEY"])
  if (preflight) return preflight
  if (req.method === 'OPTIONS') return new Response(null, { headers: CORS })
  if (req.method !== 'POST') return json({ ok: false, error: 'Method not allowed.' }, 405)
  try {
    const ctx = await context(req)
    if (!ctx) return json({ ok: false, error: 'Authentication or authorization failed.' }, 401)
    const body = await req.json().catch(() => ({}))
    let result
    switch (body.action) {
      case 'create-employee': result = await createEmployee(ctx.admin, ctx.caller, body); break
      case 'update-employee': result = await updateEmployee(ctx.admin, ctx.caller, body); break
      case 'reset-password': result = await resetPassword(ctx.admin, ctx.caller, body); break
      case 'reset-password-request': {
        result = await resetPassword(ctx.admin, ctx.caller, body)
        if (result.ok) {
          const { error } = await ctx.admin.from('password_reset_requests').update({
            status: 'Resolved', resolved_at: new Date().toISOString(), resolved_by: ctx.caller.display_name,
          }).eq('id', Number(body.requestId)).eq('status', 'Pending')
          if (error) result = { ok: false, error: 'Password changed, but reset request resolution needs support.' }
        }
        break
      }
      case 'update-owner': result = await updateOwner(ctx.admin, ctx.caller, body); break
      case 'update-config': result = await updateConfig(ctx.admin, ctx.caller, body); break
      case 'complete-onboarding': {
        if (ctx.caller.role !== 'Business Owner') { result = { ok: false, error: 'Business Owner required.' }; break }
        const { error } = await ctx.admin.rpc('complete_shop_onboarding', { p_owner: ctx.caller.auth_user_id })
        result = error ? { ok: false, error: 'Complete all required business settings, confirm your owner Auth account and set an override PIN.' } : { ok: true }
        break
      }
      case 'set-pin': {
        if (ctx.caller.role !== 'Business Owner' && ctx.caller.role !== 'Orbito Support') {
          result = { ok: false, error: 'PIN changes are not permitted.' }
        } else {
          const { error } = await ctx.admin.rpc('set_override_pin', { candidate_pin: String(body.pin ?? '') })
          result = error ? { ok: false, error: 'PIN could not be updated.' } : { ok: true }
        }
        break
      }
      default: result = { ok: false, error: 'Unsupported account action.' }
    }
    return json(result, result.ok ? 200 : 403)
  } catch (error) {
    console.error('Account administration failed.', error instanceof Error ? error.message : 'unknown error')
    return json({ ok: false, error: 'Account administration is unavailable.' }, 503)
  }
})

export const RUNTIME_CONTRACT = 'orbito-onboarding-runtime-v1'
export const REQUIRED_FUNCTIONS = ['login','account-admin','verify-pin','password-reset-request','public-track']

export async function runtimeProbe(req: Request, name: string, required: string[]) {
  if (!req.headers.has('x-orbito-preflight')) return null
  const supplied = req.headers.get('x-orbito-preflight') || ''
  const expected = Deno.env.get('PLATFORM_BRIDGE_CALL_SECRET') || ''
  const digest = async (value: string) => new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))
  const [a,b] = await Promise.all([digest(supplied),digest(expected)])
  if (req.method !== 'POST' || !expected || !supplied || a.reduce((n,v,i)=>n|(v^b[i]),0)) return Response.json({error:'Not authorized'},{status:401})
  return Response.json({contract:RUNTIME_CONTRACT,function:name,configured:required.every(k=>Boolean(Deno.env.get(k)?.trim())),runtime_checks:Object.fromEntries(required.map(k=>[k,Boolean(Deno.env.get(k)?.trim())]))},
    {headers:{'Cache-Control':'no-store'}})
}

export async function checkRuntime(admin: any, status: any) {
  let data: any, error: any
  try { ({data,error} = await admin.rpc('bridge_runtime_preflight')) } catch { error = true }
  const checks = {...data?.checks}
  if (error) checks.migrations = false
  // Exercise PostgREST under the actual Edge service client, not just a definer.
  try {
    const read = await admin.from('shop_config').select('id').eq('id',1).single()
    checks.database_reachable = !read.error && read.data?.id === 1
  } catch { checks.database_reachable = false }
  const url = Deno.env.get('SUPABASE_URL') || ''
  const anon = Deno.env.get('SUPABASE_ANON_KEY') || ''
  const call = Deno.env.get('PLATFORM_BRIDGE_CALL_SECRET') || ''
  const source = Deno.env.get('PLATFORM_BRIDGE_SOURCE_SECRET') || ''
  const endpoint = Deno.env.get('PLATFORM_BRIDGE_ENDPOINT') || ''
  let validEndpoint = false
  try { const target = new URL(endpoint);validEndpoint = target.protocol==='https:' && !target.username && !target.password && !target.search && !target.hash && target.pathname==='/functions/v1/platform-bridge' && target.origin!==url } catch {}
  checks.bridge_configuration = Boolean(call && source && call!==source && validEndpoint)
  const functions = await Promise.all(REQUIRED_FUNCTIONS.map(async name => {
    try {
      const response = await fetch(`${url}/functions/v1/${name}`,{method:'POST',redirect:'error',signal:AbortSignal.timeout(5000),
        headers:{Authorization:`Bearer ${anon}`,apikey:anon,'x-orbito-preflight':call,'Content-Type':'application/json'},body:'{}'})
      if (!response.ok) { await response.body?.cancel();return [name,false,false,false] }
      const result = await response.json()
      const deployed = result?.contract===RUNTIME_CONTRACT && result.function===name
      return [name,deployed,deployed && result.configured===true,deployed && result.runtime_checks?.TURNSTILE_SECRET===true]
    } catch { return [name,false,false,false] }
  }))
  checks.edge_functions = functions.every(([,deployed])=>deployed===true)
  checks.runtime_configuration = functions.every(([, ,configured])=>configured===true)
  let authAvailable = false
  try {
    const auth = await admin.auth.admin.listUsers({page:1,perPage:1})
    authAvailable = !auth.error && Array.isArray(auth.data?.users)
  } catch { /* No Auth bodies or identities leave the preflight. */ }
  checks.authentication = authAvailable && functions.find(([name])=>name==='login')?.[2]===true && checks.database_privileges===true && checks.rpc_privileges===true
  const keys = ['migrations','database_privileges','rpc_privileges','sequence_privileges','private_config','storage',
    'owner_reservation','bridge_mode','config_projection','database_reachable','bridge_configuration','edge_functions','runtime_configuration','authentication']
  const safeChecks = Object.fromEntries(keys.map(k=>[k,checks[k]===true]))
  const ownerAccount = ['missing','unconfirmed','ready','active','conflict'].includes(data?.owner_account) ? data.owner_account : 'missing'
  return {...status,contract:RUNTIME_CONTRACT,checks:safeChecks,owner_account:ownerAccount,
    runtime_details:{functions:Object.fromEntries(functions.map(([name,deployed])=>[name,deployed===true])),turnstile:functions.filter(([name])=>['login','password-reset-request'].includes(String(name))).every(([, , ,turnstile])=>turnstile===true)},
    infrastructure:keys.every(k=>safeChecks[k]) && ownerAccount!=='conflict' ? 'ready':'pending'}
}

import { runtimeProbe } from '../_shared/runtime-preflight.ts'
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.108.2'

const TURNSTILE_SECRET = Deno.env.get('TURNSTILE_SECRET') ?? ''
const SUPABASE_URL = Deno.env.get('SUPABASE_URL') ?? ''
const SUPABASE_ANON = Deno.env.get('SUPABASE_ANON_KEY') ?? ''
const SUPABASE_SERVICE_ROLE = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
const PLATFORM_SUPABASE_URL = Deno.env.get('PLATFORM_SUPABASE_URL') ?? ''
const PLATFORM_SUPABASE_ANON = Deno.env.get('PLATFORM_SUPABASE_ANON') ?? ''
const PLATFORM_AUTH_EMAIL = normalizeEmail(Deno.env.get('PLATFORM_AUTH_EMAIL') ?? '')

const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

type AppProfile = {
  auth_user_id: string
  employee_id: number | null
  email: string
  display_name: string
  role: 'Business Owner' | 'Manager' | 'Cashier' | 'Technician' | 'Orbito Support'
  status: 'Active' | 'Inactive'
}

type LegacyIdentity = {
  normalized_email: string
  identity_type: 'owner' | 'employee'
  employee_id: number | null
  display_name: string
  app_role: AppProfile['role']
  app_status: AppProfile['status']
}

function normalizeEmail(value: string) {
  return value.toLowerCase().trim()
}

function clientSupportEmail() {
  let projectRef = ''
  try {
    projectRef = new URL(SUPABASE_URL).hostname.split('.')[0] ?? ''
  } catch {
    throw new Error('Client Supabase project identity is invalid.')
  }
  projectRef = projectRef.toLowerCase().replace(/[^a-z0-9-]/g, '')
  if (!projectRef) throw new Error('Client Supabase project identity is unavailable.')
  return `orbitosupport+${projectRef}@support.orbito.internal`
}

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
  })
}

function publicProfile(profile: AppProfile) {
  return {
    authUserId: profile.auth_user_id,
    employeeId: profile.employee_id,
    email: profile.email,
    displayName: profile.display_name,
    role: profile.role,
    status: profile.status,
  }
}

function loginResponse(profile: AppProfile, session: { access_token: string; refresh_token: string; expires_at?: number }) {
  return {
    ok: true,
    session: {
      access_token: session.access_token,
      refresh_token: session.refresh_token,
      expires_at: session.expires_at,
    },
    profile: publicProfile(profile),
    isAdmin: ['Business Owner', 'Orbito Support'].includes(profile.role),
    isSupportAdmin: profile.role === 'Orbito Support',
    employee: {
      id: profile.employee_id ?? undefined,
      name: profile.display_name,
      role: profile.role,
      email: profile.email,
    },
  }
}

async function verifyTurnstile(token: string, remoteIp: string | null) {
  if (!token || !TURNSTILE_SECRET) return false
  const form = new URLSearchParams({ secret: TURNSTILE_SECRET, response: token })
  if (remoteIp) form.set('remoteip', remoteIp)

  try {
    const response = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: form,
    })
    const outcome = await response.json().catch(() => ({ success: false }))
    return outcome.success === true
  } catch (error) {
    console.error('Turnstile verification request failed.', error instanceof Error ? error.message : 'unknown error')
    return false
  }
}

function clients() {
  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE || !SUPABASE_ANON) {
    throw new Error('Client Supabase authentication environment is incomplete.')
  }
  const options = { auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false } }
  return {
    admin: createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE, options),
    auth: createClient(SUPABASE_URL, SUPABASE_ANON, options),
  }
}

async function shopIsSuspended(admin: ReturnType<typeof createClient>) {
  const { data, error } = await admin.from('shop_config').select('suspended').eq('id', 1).single()
  if (error || !data) throw new Error('Shop access state is unavailable.')
  return data.suspended === true
}

async function findAppProfile(admin: ReturnType<typeof createClient>, email: string): Promise<AppProfile | null> {
  const { data, error } = await admin
    .from('app_users')
    .select('auth_user_id, employee_id, email, display_name, role, status')
    .eq('email', email)
    .maybeSingle()
  if (error) throw new Error('Application identity lookup failed.')
  return data as AppProfile | null
}

async function findSupportProfile(admin: ReturnType<typeof createClient>): Promise<AppProfile | null> {
  const { data, error } = await admin
    .from('app_users')
    .select('auth_user_id, employee_id, email, display_name, role, status')
    .eq('role', 'Orbito Support')
    .maybeSingle()
  if (error) throw new Error('Support identity lookup failed.')
  return data as AppProfile | null
}

async function findAuthUserByEmail(admin: ReturnType<typeof createClient>, email: string) {
  for (let page = 1; page <= 100; page += 1) {
    const { data, error } = await admin.auth.admin.listUsers({ page, perPage: 1000 })
    if (error) throw new Error('Authentication identity lookup failed.')
    const match = data.users.find((user) => normalizeEmail(user.email ?? '') === email)
    if (match) return match
    if (data.users.length < 1000) return null
  }
  throw new Error('Authentication identity lookup exceeded its safe page limit.')
}

async function signInMappedUser(
  admin: ReturnType<typeof createClient>,
  auth: ReturnType<typeof createClient>,
  profile: AppProfile,
  password: string,
) {
  if (profile.status !== 'Active') return { ok: false, error: 'Incorrect email or password.' }
  if (profile.role !== 'Orbito Support' && await shopIsSuspended(admin)) {
    return { ok: false, error: 'This shop account is suspended. Contact your service provider.' }
  }
  const { data, error } = await auth.auth.signInWithPassword({ email: profile.email, password })
  if (error || !data.session || !data.user || data.user.id !== profile.auth_user_id) {
    return { ok: false, error: 'Incorrect email or password.' }
  }
  await admin.from('legacy_auth_credentials').delete().eq('normalized_email', profile.email)
  return loginResponse(profile, data.session)
}

async function signInReservedOwner(auth: ReturnType<typeof createClient>, email: string, password: string) {
  const { data, error } = await auth.auth.signInWithPassword({ email, password })
  if (error || !data.user || !data.session) return { ok: false, error: 'Incorrect email or password.' }
  const { data: verified, error: verifyError } = await auth.auth.getUser(data.session.access_token)
  if (verifyError || !verified.user || verified.user.id !== data.user.id || normalizeEmail(verified.user.email ?? '') !== email) {
    return { ok: false, error: 'Authentication could not be verified.' }
  }
  // The signed-in client invokes a no-argument RPC: UUID comes from the verified
  // JWT, while email/name/role come from the protected Shop reservation.
  const { data: profile, error: claimError } = await auth.rpc('activate_reserved_owner')
  if (claimError || !profile || profile.auth_user_id !== verified.user.id || profile.email !== email
    || profile.role !== 'Business Owner' || profile.employee_id !== null || profile.status !== 'Active') {
    await auth.auth.signOut({ scope: 'local' })
    return { ok: false, error: 'This account is not authorized for this Shop, or owner activation is not ready. Contact your operator.' }
  }
  return loginResponse(profile, data.session)
}

async function verifyLegacyIdentity(
  admin: ReturnType<typeof createClient>,
  email: string,
  password: string,
): Promise<LegacyIdentity | null> {
  const { data: vault, error: vaultError } = await admin
    .from('legacy_auth_credentials')
    .select('normalized_email')
    .eq('normalized_email', email)
    .maybeSingle()
  if (vaultError) throw new Error('Legacy authentication vault lookup failed.')

  if (vault) {
    const { data, error } = await admin.rpc('verify_legacy_credential', {
      candidate_email: email,
      candidate_password: password,
    })
    if (error) throw new Error('Legacy credential verification failed.')
    return (data?.[0] as LegacyIdentity | undefined) ?? null
  }

  // Applied Phase 2 constraints require legacy plaintext columns to stay NULL.
  // Unmigrated accounts may still use the hash vault above, never plaintext.
  return null
}

async function migrateLegacyLogin(
  admin: ReturnType<typeof createClient>,
  auth: ReturnType<typeof createClient>,
  identity: LegacyIdentity,
  password: string,
) {
  if (identity.app_status !== 'Active') return { ok: false, error: 'Incorrect email or password.' }
  if (await shopIsSuspended(admin)) {
    return { ok: false, error: 'This shop account is suspended. Contact your service provider.' }
  }
  if (await findAuthUserByEmail(admin, identity.normalized_email)) {
    return { ok: false, error: 'This account needs administrator recovery before it can sign in.' }
  }

  const { data: created, error: createError } = await admin.auth.admin.createUser({
    email: identity.normalized_email,
    password,
    email_confirm: true,
  })
  if (createError || !created.user) return { ok: false, error: 'Account migration could not be completed.' }

  const profile: AppProfile = {
    auth_user_id: created.user.id,
    employee_id: identity.employee_id,
    email: identity.normalized_email,
    display_name: identity.display_name,
    role: identity.app_role,
    status: identity.app_status,
  }
  const { error: mappingError } = await admin.from('app_users').insert(profile)
  if (mappingError) {
    await admin.auth.admin.deleteUser(created.user.id)
    return { ok: false, error: 'Account migration could not be completed.' }
  }

  const { data: signedIn, error: signInError } = await auth.auth.signInWithPassword({
    email: identity.normalized_email,
    password,
  })
  if (signInError || !signedIn.session || !signedIn.user || signedIn.user.id !== created.user.id) {
    await admin.from('app_users').delete().eq('auth_user_id', created.user.id)
    await admin.auth.admin.deleteUser(created.user.id)
    return { ok: false, error: 'Account migration could not be completed.' }
  }

  const { error: consumeError } = await admin
    .from('legacy_auth_credentials')
    .delete()
    .eq('normalized_email', identity.normalized_email)
  if (consumeError) console.error('Legacy credential cleanup is pending for a mapped account.')
  return loginResponse(profile, signedIn.session)
}

async function verifyPlatformSupport(email: string, password: string) {
  if (!PLATFORM_SUPABASE_URL || !PLATFORM_SUPABASE_ANON || !PLATFORM_AUTH_EMAIL) {
    return { ok: false, error: 'Support access is not configured for this client.' }
  }
  if (email !== PLATFORM_AUTH_EMAIL) return { ok: false, error: 'Incorrect support credentials.' }

  try {
    const response = await fetch(
      `${PLATFORM_SUPABASE_URL.replace(/\/$/, '')}/auth/v1/token?grant_type=password`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', apikey: PLATFORM_SUPABASE_ANON },
        body: JSON.stringify({ email, password }),
      },
    )
    const result = await response.json().catch(() => ({}))
    const authenticatedEmail = normalizeEmail(result?.user?.email ?? '')
    if (!response.ok || !result?.user?.id || authenticatedEmail !== PLATFORM_AUTH_EMAIL) {
      return { ok: false, error: 'Incorrect support credentials.' }
    }
    return { ok: true, userId: String(result.user.id), email: authenticatedEmail }
  } catch (error) {
    console.error('Platform authentication request failed.', error instanceof Error ? error.message : 'unknown error')
    return { ok: false, error: 'Support authentication service is unavailable.' }
  }
}

async function bootstrapSupportSession(
  admin: ReturnType<typeof createClient>,
  auth: ReturnType<typeof createClient>,
  platformUserId: string,
  platformEmail: string,
  userAgent: string | null,
) {
  const supportEmail = clientSupportEmail()
  let profile = await findSupportProfile(admin)
  let newlyCreatedUserId: string | null = null

  if (profile && normalizeEmail(profile.email) !== supportEmail) {
    return { ok: false, error: 'Client support identity requires administrator recovery.' }
  }

  if (!profile) {
    const emailProfile = await findAppProfile(admin, supportEmail)
    if (emailProfile) {
      return { ok: false, error: 'Client support identity conflicts with an application account.' }
    }

    let authUser = await findAuthUserByEmail(admin, supportEmail)
    if (!authUser) {
      const { data: created, error: createError } = await admin.auth.admin.createUser({
        email: supportEmail,
        email_confirm: true,
        app_metadata: { app_identity: 'orbito_client_support' },
      })
      if (createError || !created.user) return { ok: false, error: 'Support session could not be created.' }
      newlyCreatedUserId = created.user.id
      authUser = created.user
    }

    profile = {
      auth_user_id: authUser.id,
      employee_id: null,
      email: supportEmail,
      display_name: 'Orbito Support',
      role: 'Orbito Support',
      status: 'Active',
    }
    const { error: mappingError } = await admin.from('app_users').insert(profile)
    if (mappingError) {
      if (newlyCreatedUserId) await admin.auth.admin.deleteUser(newlyCreatedUserId)
      return { ok: false, error: 'Support session could not be created.' }
    }
  } else {
    const { data, error } = await admin.auth.admin.getUserById(profile.auth_user_id)
    const authUser = data?.user
    if (error || !authUser || authUser.id !== profile.auth_user_id
      || normalizeEmail(authUser.email ?? '') !== supportEmail || profile.employee_id !== null) {
      return { ok: false, error: 'Client support identity requires administrator recovery.' }
    }
  }

  if (profile.status !== 'Active') return { ok: false, error: 'Support access is inactive.' }
  const { data: linkData, error: linkError } = await admin.auth.admin.generateLink({
    type: 'magiclink',
    email: supportEmail,
  })
  const tokenHash = linkData?.properties?.hashed_token
  if (linkError || !tokenHash) {
    if (newlyCreatedUserId) {
      await admin.from('app_users').delete().eq('auth_user_id', newlyCreatedUserId)
      await admin.auth.admin.deleteUser(newlyCreatedUserId)
    }
    return { ok: false, error: 'Support session could not be created.' }
  }

  const { data: verified, error: verifyError } = await auth.auth.verifyOtp({ token_hash: tokenHash, type: 'email' })
  if (verifyError || !verified.session || !verified.user || verified.user.id !== profile.auth_user_id) {
    if (newlyCreatedUserId) {
      await admin.from('app_users').delete().eq('auth_user_id', newlyCreatedUserId)
      await admin.auth.admin.deleteUser(newlyCreatedUserId)
    }
    return { ok: false, error: 'Support session could not be created.' }
  }

  const { error: auditError } = await admin.from('support_access_log').insert({
    platform_user_id: platformUserId,
    platform_email: platformEmail,
    client_auth_user_id: profile.auth_user_id,
    event: 'support_login',
    user_agent: userAgent,
  })
  if (auditError) return { ok: false, error: 'Support access audit is unavailable. Access denied.' }
  return loginResponse(profile, verified.session)
}

Deno.serve(async (req: Request) => {
  const preflight = await runtimeProbe(req,'login',["SUPABASE_URL","SUPABASE_ANON_KEY","SUPABASE_SERVICE_ROLE_KEY","TURNSTILE_SECRET"])
  if (preflight) return preflight
  if (req.method === 'OPTIONS') return new Response(null, { headers: CORS_HEADERS })
  if (req.method !== 'POST') return json({ ok: false, error: 'Method not allowed.' }, 405)

  let body: { email?: string; password?: string; turnstileToken?: string; mode?: string }
  try {
    body = await req.json()
  } catch {
    return json({ ok: false, error: 'Invalid request body.' }, 400)
  }

  const email = normalizeEmail(body.email ?? '')
  const password = body.password ?? ''
  const mode = body.mode === 'support' ? 'support' : 'shop'
  if (!email || !password) return json({ ok: false, error: 'Email and password are required.' }, 400)

  const remoteIp = req.headers.get('cf-connecting-ip') || req.headers.get('x-forwarded-for')
  if (!await verifyTurnstile(body.turnstileToken ?? '', remoteIp)) {
    return json({ ok: false, error: 'Verification failed. Please try again.' }, 403)
  }

  try {
    const { admin, auth } = clients()
    if (mode === 'support') {
      const support = await verifyPlatformSupport(email, password)
      if (!support.ok || !support.userId || !support.email) return json(support, 401)
      const result = await bootstrapSupportSession(
        admin, auth, support.userId, support.email, req.headers.get('user-agent'),
      )
      return json(result, result.ok ? 200 : 401)
    }

    const mapped = await findAppProfile(admin, email)
    if (mapped) {
      const result = await signInMappedUser(admin, auth, mapped, password)
      return json(result, result.ok ? 200 : 401)
    }
    const { data: setup, error: setupError } = await admin.from('shop_config')
