export async function runtimeProbe(req: Request, name: string, required: string[]) {
  if (!req.headers.has('x-orbito-preflight')) return null
  const supplied = req.headers.get('x-orbito-preflight') || ''
  const expected = Deno.env.get('PLATFORM_BRIDGE_CALL_SECRET') || ''
  const digest = async (value: string) => new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))
  const [a,b] = await Promise.all([digest(supplied),digest(expected)])
  if (req.method !== 'POST' || !expected || !supplied || a.reduce((n,v,i)=>n|(v^b[i]),0)) return Response.json({error:'Not authorized'},{status:401})
  return Response.json({contract:RUNTIME_CONTRACT,function:name,configured:required.every(k=>Boolean(Deno.env.get(k)?.trim())),runtime_checks:Object.fromEntries(required.map(k=>[k,Boolean(Deno.env.get(k)?.trim())]))},
    {headers:{'Cache-Control':'no-store'}})
}

export async function checkRuntime(admin: any, status: any) {
  let data: any, error: any
  try { ({data,error} = await admin.rpc('bridge_runtime_preflight')) } catch { error = true }
  const checks = {...data?.checks}
  if (error) checks.migrations = false
  // Exercise PostgREST under the actual Edge service client, not just a definer.
  try {
    const read = await admin.from('shop_config').select('id').eq('id',1).single()
    checks.database_reachable = !read.error && read.data?.id === 1
  } catch { checks.database_reachable = false }
  const url = Deno.env.get('SUPABASE_URL') || ''
  const anon = Deno.env.get('SUPABASE_ANON_KEY') || ''
  const call = Deno.env.get('PLATFORM_BRIDGE_CALL_SECRET') || ''
  const source = Deno.env.get('PLATFORM_BRIDGE_SOURCE_SECRET') || ''
  const endpoint = Deno.env.get('PLATFORM_BRIDGE_ENDPOINT') || ''
  let validEndpoint = false
  try { const target = new URL(endpoint);validEndpoint = target.protocol==='https:' && !target.username && !target.password && !target.search && !target.hash && target.pathname==='/functions/v1/platform-bridge' && target.origin!==url } catch {}
  checks.bridge_configuration = Boolean(call && source && call!==source && validEndpoint)
  const functions = await Promise.all(REQUIRED_FUNCTIONS.map(async name => {
    try {
      const response = await fetch(`${url}/functions/v1/${name}`,{method:'POST',redirect:'error',signal:AbortSignal.timeout(5000),
        headers:{Authorization:`Bearer ${anon}`,apikey:anon,'x-orbito-preflight':call,'Content-Type':'application/json'},body:'{}'})
      if (!response.ok) { await response.body?.cancel();return [name,false,false,false] }
      const result = await response.json()
      const deployed = result?.contract===RUNTIME_CONTRACT && result.function===name
      return [name,deployed,deployed && result.configured===true,deployed && result.runtime_checks?.TURNSTILE_SECRET===true]
    } catch { return [name,false,false,false] }
  }))
  checks.edge_functions = functions.every(([,deployed])=>deployed===true)
  checks.runtime_configuration = functions.every(([, ,configured])=>configured===true)
  let authAvailable = false
  try {
    const auth = await admin.auth.admin.listUsers({page:1,perPage:1})
    authAvailable = !auth.error && Array.isArray(auth.data?.users)
  } catch { /* No Auth bodies or identities leave the preflight. */ }
  checks.authentication = authAvailable && functions.find(([name])=>name==='login')?.[2]===true && checks.database_privileges===true && checks.rpc_privileges===true
  const keys = ['migrations','database_privileges','rpc_privileges','sequence_privileges','private_config','storage',
    'owner_reservation','bridge_mode','config_projection','database_reachable','bridge_configuration','edge_functions','runtime_configuration','authentication']
  const safeChecks = Object.fromEntries(keys.map(k=>[k,checks[k]===true]))
  const ownerAccount = ['missing','unconfirmed','ready','active','conflict'].includes(data?.owner_account) ? data.owner_account : 'missing'
  return {...status,contract:RUNTIME_CONTRACT,checks:safeChecks,owner_account:ownerAccount,
    runtime_details:{functions:Object.fromEntries(functions.map(([name,deployed])=>[name,deployed===true])),turnstile:functions.filter(([name])=>['login','password-reset-request'].includes(String(name))).every(([, , ,turnstile])=>turnstile===true)},
    infrastructure:keys.every(k=>safeChecks[k]) && ownerAccount!=='conflict' ? 'ready':'pending'}
}

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.108.2'
import { onboardingOperation } from './onboarding.ts'

// Server-to-server only. No browser CORS or caller-supplied destination/source.
// Leave deployment and scheduling disabled until Platform implements contract v1.
const reply = (status: number, body: unknown) => new Response(JSON.stringify(body), {
  status, headers: { 'Content-Type': 'application/json' },
})
async function sameSecret(left: string, right: string) {
  if (!left || !right) return false
  const encode = new TextEncoder()
  const [a, b] = await Promise.all([left, right].map(s => crypto.subtle.digest('SHA-256', encode.encode(s))))
  return new Uint8Array(a).reduce((difference, byte, i) => difference | (byte ^ new Uint8Array(b)[i]), 0) === 0
}

Deno.serve(async req => {
  if (req.method !== 'POST') return reply(405, { error: 'POST required' })
  const callSecret = Deno.env.get('PLATFORM_BRIDGE_CALL_SECRET') ?? ''
  const token = req.headers.get('authorization')?.match(/^Bearer\s+(.+)$/i)?.[1] ?? ''
  if (!await sameSecret(token, callSecret)) return reply(401, { error: 'Not authorized' })

  let operation: any = {}
  try {
    const text = await req.text()
    if (text.length > 16384) return reply(413, { error: 'Request too large' })
    operation = text ? JSON.parse(text) : {}
  } catch { return reply(400, { error: 'Invalid bridge request' }) }
  if (operation?.operation) {
    const admin = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
      { auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false },
        global: { fetch: (input: RequestInfo | URL, init?: RequestInit) => fetch(input, { ...init, redirect:'error',
          signal: AbortSignal.any([AbortSignal.timeout(20000), ...(init?.signal ? [init.signal] : [])]) }) } })
    try { return reply(200, await onboardingOperation(admin, operation)) }
    catch (error) { return reply(409, { error: error instanceof Error ? error.message : 'Onboarding unavailable' }) }
  }

  const endpoint = Deno.env.get('PLATFORM_BRIDGE_ENDPOINT') ?? ''
  const secret = Deno.env.get('PLATFORM_BRIDGE_SOURCE_SECRET') ?? ''
  if (!endpoint || !secret) return reply(200, { enabled: false })
  let destination: URL
  try {
    destination = new URL(endpoint)
    if (destination.protocol !== 'https:' || destination.username || destination.password) throw new Error()
  } catch { return reply(503, { error: 'Bridge configuration unavailable' }) }

  // Caller authentication above is separate from privileged Shop DB access.
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
  const admin = createClient(Deno.env.get('SUPABASE_URL') ?? '', serviceKey,
    { auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false } })
  try {
    const { data: batch, error } = await admin.rpc('bridge_claim_outbox', { p_limit: 50 })
    if (error) throw new Error('Could not lease outbox')
    if (!batch?.enabled) return reply(200, { enabled: false })

    // No network work occurs inside Shop financial transactions. Redirects are
    // rejected so the configured per-source credential cannot leak to another host.
    let response: any
    try {
      const received = await fetch(destination, {
        method: 'POST', redirect: 'error', signal: AbortSignal.timeout(15000),
        headers: { 'Authorization': `Bearer ${secret}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ schema_version: 1, source_id: batch.source_id,
          client_binding: batch.client_binding, events: batch.events }),
      })
      if (!received.ok) throw new Error('Platform did not accept delivery')
      const text = await received.text()
      if (text.length > 1024 * 1024) throw new Error('Platform response too large')
      response = JSON.parse(text)
      if (response.schema_version !== 1 || response.source_id !== batch.source_id
        || !Array.isArray(response.acknowledgements)) throw new Error('Invalid Platform reply')
    } catch {
      await Promise.all(batch.events.map((event: any) => admin.rpc('bridge_finish_delivery', {
        p_event_id: event.event_id, p_lease_id: batch.lease_id, p_accepted: false,
      })))
      return reply(502, { error: 'Platform unavailable; events remain queued' })
    }

    let acknowledged = 0
    for (const event of batch.events) {
      const matches = response.acknowledgements.filter((ack: any) => ack?.event_id === event.event_id)
      // Duplicate/conflicting acknowledgements never silently count as accepted.
      const accepted = matches.length === 1 && ['accepted', 'duplicate'].includes(matches[0].status)
      const { data: done, error: ackError } = await admin.rpc('bridge_finish_delivery', {
        p_event_id: event.event_id, p_lease_id: batch.lease_id, p_accepted: accepted,
      })
      if (ackError) throw new Error('Could not persist delivery outcome')
      if (accepted && done) acknowledged++
    }
    // A failed projection does not roll back already durable per-event ACKs.
    if (response.billing != null) {
      const { error: projectionError } = await admin.rpc('bridge_apply_billing', {
        p_source_id: batch.source_id, p_version: response.billing.sync_version, p_payload: response.billing.payload,
      })
      if (projectionError) throw new Error('Billing revision rejected')
    }
    if (response.resupply_updates != null) {
      if (!Array.isArray(response.resupply_updates) || response.resupply_updates.length > 100) throw new Error('Invalid lifecycle revisions')
      for (const update of response.resupply_updates) {
        const { error: lifecycleError } = await admin.rpc('bridge_apply_resupply', {
          p_source_id: batch.source_id, p_request_id: update.request_id, p_version: update.sync_version,
          p_status: update.status, p_updated_at: update.platform_updated_at,
        })
        if (lifecycleError) throw new Error('Lifecycle revision rejected')
      }
    }
    return reply(200, { enabled: true, acknowledged })
  } catch {
    // Never return service secrets, remote payloads or financial internals.
    return reply(503, { error: 'Bridge synchronization incomplete; retry safely' })
  }
})

import { checkRuntime } from '../_shared/runtime-preflight.ts'
// Called only after the bridge's opaque call credential has been authenticated.
export async function onboardingOperation(admin: any, body: any) {
  const rpc = async (action: string, payload: any = {}) => {
    const { data, error } = await admin.rpc('bridge_onboarding', { p_action: action, p_payload: payload })
    if (error) throw new Error('Shop identity, readiness or operation conflict. Retry the same request; reconcile an existing Shop instead of resetting it.')
    return data
  }
  if (['config-read','config-write'].includes(body.operation)) return rpc(body.operation, body)
  if (['status','preflight'].includes(body.operation)) return checkRuntime(admin,await rpc('status'))
  if (body.operation === 'bootstrap') return checkRuntime(admin,await rpc('reserve',body.payload))
  if (body.operation !== 'invite-owner') throw new Error('Unsupported bridge operation')
  const payload = body.payload
  let redirect: URL
  try {
    redirect = new URL(payload.shop_url)
    if (redirect.protocol !== 'https:' || redirect.username || redirect.password || redirect.search || redirect.hash) throw new Error()
    redirect = new URL('/invite/accept', redirect)
  } catch { throw new Error('Configure a valid HTTPS Shop URL and allow /invite/accept in Shop Auth redirect URLs.') }
  const claim = await rpc('claim', payload)
  if (claim.already_provisioned) return checkRuntime(admin,claim)
  try {
    const { data, error } = await admin.auth.admin.inviteUserByEmail(payload.owner_email, {
      redirectTo: redirect.href,
      data: { owner_name: payload.owner_name, orbito_bootstrap_request: claim.request_id },
    })
    if (error || !data?.user) {
      // SDK fetch failures may be returned, rather than thrown. A network/5xx
      // result cannot prove Auth did not commit; preserve the recovery lease.
      if (!error || error.status < 400 || error.status >= 500 || !Number.isFinite(error.status)
        || error.name === 'AuthRetryableFetchError') throw new Error('Unknown Auth outcome')
      await rpc('failed', { lease_id: claim.lease_id })
      return { ...await checkRuntime(admin,await rpc('status')), invitation: 'failed' }
    }
    return { ...await checkRuntime(admin,await rpc('finish', { auth_user_id: data.user.id })), invitation: 'sent' }
  } catch (error) {
    // Unknown Auth outcomes retain the short lease. Retry recovers the committed
    // invitation by reserved email + request correlation without sending twice.
    return { ...await checkRuntime(admin,await rpc('status')), invitation: 'pending' }
  }
}
